@@ -1,9 +1,239 @@
+type Version = readonly [number, number, number];
+type PartialVersion = readonly [number | null, number | null, number | null];
+
+function parseVersion(v: string): Version {
+  const parts = v.split(".");
+  if (parts.length !== 3) throw new Error(`Invalid version: ${v}`);
+  const nums = parts.map(p => {
+    if (!/^\d+$/.test(p)) throw new Error(`Invalid version: ${v}`);
+    const n = Number(p);
+    if (!Number.isInteger(n) || n < 0) throw new Error(`Invalid version: ${v}`);
+    return n;
+  });
+  return [nums[0], nums[1], nums[2]];
+}
+
+function parsePartialVersion(v: string): PartialVersion {
+  if (v === "*" || v === "x" || v === "X") return [null, null, null];
+
+  const parts = v.split(".");
+  if (parts.length < 1 || parts.length > 3) throw new Error(`Invalid version: ${v}`);
+
+  const result: [number | null, number | null, number | null] = [null, null, null];
+  let seenWildcard = false;
+
+  for (let i = 0; i < parts.length; i++) {
+    const p = parts[i];
+    const isWildcard = p === "x" || p === "X" || p === "*";
+    if (isWildcard) {
+      seenWildcard = true;
+      result[i] = null;
+    } else if (seenWildcard) {
+      throw new Error(`Invalid version: ${v}`);
+    } else {
+      if (!/^\d+$/.test(p)) throw new Error(`Invalid version: ${v}`);
+      const n = Number(p);
+      if (!Number.isInteger(n) || n < 0) throw new Error(`Invalid version: ${v}`);
+      result[i] = n;
+    }
+  }
+
